  blocker?: string;
  retry?: {
    attempt: number;
    maxAttempts: number;
    classification: string;
    safeToRetry: boolean;
  };
  children?: WorkNode[];
}

export type EvidenceState =
  | "supported"
  | "conflicting"
  | "unknown"
  | "operator-provided"
  | "calculated";

export interface Requirement {
  id: string;
  label: string;
  value: string;
