import { FormEvent, useState } from "react";

import type {
  OperatorRun,
  ProposalEdit,
} from "./types";

interface ActionRailProps {
  run: OperatorRun;
  onSaveProposal: (edit: ProposalEdit) => Promise<void>;
  onDecideProposal: (decision: "approve" | "reject") => Promise<void>;
}

export function ActionRail({
  run,
  onSaveProposal,
  onDecideProposal,
}: ActionRailProps) {
  const [proposalView, setProposalView] = useState<"preview" | "diff">("preview");
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [edit, setEdit] = useState<ProposalEdit>(() => ({
    recipient: run.proposal?.current.recipient ?? "",
    subject: run.proposal?.current.subject ?? "",
    body: run.proposal?.current.body ?? "",
  }));
  const proposal = run.proposal;

  async function handleSave(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setIsSaving(true);
    await onSaveProposal(edit);
    setIsSaving(false);
    setIsEditing(false);
  }

  return (
    <aside className="action-rail" aria-labelledby="output-heading">
      <section className="artifact-section">
        <div className="rail-heading">
          <div>
            <p className="section-index">Outputs</p>
            <h2 id="output-heading">Artifact rail</h2>
          </div>
          <span>{run.artifacts.length}</span>
        </div>
        {run.artifacts.length ? (
          <ul className="artifact-list">
            {run.artifacts.map((artifact) => (
              <li key={artifact.id}>
                <span className="file-mark" aria-hidden="true">
                  {artifact.kind.slice(0, 2).toUpperCase()}
                </span>
                <div>
                  <strong>{artifact.filename}</strong>
                  <small>
                    v{artifact.version} · {artifact.sizeLabel}
                  </small>
                  <span className={`artifact-status ${artifact.status}`}>
                    {artifact.status}
                  </span>
                </div>
                {artifact.status !== "building" ? (
                  <a href={artifact.downloadUrl}>Download</a>
                ) : (
                  <span className="building-label">Rebuilding</span>
                )}
              </li>
            ))}
          </ul>
        ) : (
          <p className="rail-empty">Artifacts appear here as outputs stabilize.</p>
        )}
      </section>

      {proposal ? (
        <section className="proposal-card" aria-labelledby="proposal-heading">
          <header>
            <div>
              <p className="section-index">Protected action</p>
              <h2 id="proposal-heading">RFQ proposal</h2>
            </div>
            <span className={`proposal-status ${proposal.status}`}>
              {proposal.status.replace("_", " ")}
            </span>
          </header>

          <div className="proposal-meta">
            <span>Version {proposal.current.version}</span>
            <span>{proposal.riskClass}</span>
          </div>
          <p className="policy-decision">{proposal.policyDecision}</p>

          {isEditing ? (
            <form className="proposal-form" onSubmit={handleSave}>
              <label>
                Recipient
                <input
                  required
                  type="email"
                  value={edit.recipient}
                  onChange={(event) =>
                    setEdit({ ...edit, recipient: event.target.value })
                  }
                />
              </label>
              <label>
                Subject
                <input
                  required
                  value={edit.subject}
                  onChange={(event) =>
                    setEdit({ ...edit, subject: event.target.value })
                  }
                />
              </label>
              <label>
                Exact body
                <textarea
                  required
                  rows={6}
                  value={edit.body}
                  onChange={(event) =>
                    setEdit({ ...edit, body: event.target.value })
                  }
                />
              </label>
              <div className="button-pair">
                <button type="submit" disabled={isSaving}>
                  {isSaving ? "Saving…" : "Save as new version"}
                </button>
                <button
                  className="secondary-button"
                  type="button"
                  onClick={() => setIsEditing(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          ) : (
            <>
              <div
                className="proposal-tabs"
                role="tablist"
                aria-label="Proposal version views"
              >
                <button
                  type="button"
                  role="tab"
                  aria-selected={proposalView === "preview"}
                  onClick={() => setProposalView("preview")}
                >
                  Exact preview
                </button>
                <button
                  type="button"
                  role="tab"
                  aria-selected={proposalView === "diff"}
                  disabled={!proposal.previous}
                  onClick={() => setProposalView("diff")}
                >
                  v{proposal.previous?.version ?? "–"} → v
                  {proposal.current.version}
                </button>
              </div>
              {proposalView === "preview" ? (
                <div className="proposal-preview" role="tabpanel">
                  <dl>
                    <div>
                      <dt>To</dt>
                      <dd>{proposal.current.recipient}</dd>
                    </div>
                    <div>
                      <dt>Subject</dt>
                      <dd>{proposal.current.subject}</dd>
                    </div>
                  </dl>
                  <p>{proposal.current.body}</p>
                  <small>{proposal.current.digest}</small>
                </div>
              ) : (
                <div className="proposal-diff" role="tabpanel">
                  <p>
                    <del>
                      {proposal.previous?.subject ?? "No prior subject"}
                    </del>
                    <ins>{proposal.current.subject}</ins>
                  </p>
                  <p>
                    <del>{proposal.previous?.body ?? "No prior body"}</del>
                    <ins>{proposal.current.body}</ins>
                  </p>
                  <small>
                    Editing invalidated {proposal.previous?.digest}. Approval
                    binds only {proposal.current.digest}.
                  </small>
                </div>
              )}
              {proposal.status === "pending_approval" ? (
                <>
                  <button
                    className="edit-proposal"
                    type="button"
                    onClick={() => {
                      setEdit({
                        recipient: proposal.current.recipient,
                        subject: proposal.current.subject,
                        body: proposal.current.body,
                      });
                      setIsEditing(true);
                    }}
                  >
                    Edit proposal
                  </button>
                  <div className="approval-actions">
                    <button
                      type="button"
                      onClick={() => void onDecideProposal("approve")}
                    >
                      Approve exact v{proposal.current.version}
                    </button>
                    <button
                      className="danger-button"
                      type="button"
                      onClick={() => void onDecideProposal("reject")}
                    >
                      Reject
                    </button>
                  </div>
                </>
              ) : (
                <p className="decision-receipt" role="status">
                  {proposal.status === "approved"
                    ? `Approved by ${proposal.approvedBy}`
                    : "Proposal rejected; no action is authorized."}
                </p>
              )}
            </>
          )}
        </section>
      ) : null}
    </aside>
  );
}

import { FormEvent, useState } from "react";

import type { OperatorCommand } from "./types";

interface CommandComposerProps {
  commands: OperatorCommand[];
  onSend: (mode: "queue" | "redirect", text: string) => Promise<void>;
}

export function CommandComposer({
  commands,
  onSend,
}: CommandComposerProps) {
  const [mode, setMode] = useState<"queue" | "redirect">("queue");
  const [text, setText] = useState("");
  const [isSending, setIsSending] = useState(false);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const commandText = text.trim();
    if (!commandText) {
      return;
    }
    setIsSending(true);
    await onSend(mode, commandText);
    setText("");
    setIsSending(false);
  }

  return (
    <section className="command-dock" aria-labelledby="command-heading">
      <div className="command-history">
        <p className="section-index" id="command-heading">
          Operator instructions
        </p>
        {commands.length ? (
          <ol>
            {commands.slice(0, 2).map((command) => (
              <li key={command.id}>
                <span className={`command-mode ${command.mode}`}>
                  {command.mode}
                </span>
                <p>{command.text}</p>
                <small>
                  {command.status} · {command.createdLabel}
                </small>
              </li>
            ))}
          </ol>
        ) : (
          <p className="command-empty">No operator instructions yet.</p>
        )}
      </div>
      <form onSubmit={submit}>
        <fieldset>
          <legend className="sr-only">Instruction behavior</legend>
          <label>
            <input
              type="radio"
              name="instruction-mode"
              value="queue"
              checked={mode === "queue"}
              onChange={() => setMode("queue")}
            />
            Queue
          </label>
          <label>
            <input
              type="radio"
              name="instruction-mode"
              value="redirect"
              checked={mode === "redirect"}
              onChange={() => setMode("redirect")}
            />
            Redirect
          </label>
        </fieldset>
        <label className="sr-only" htmlFor="operator-instruction">
          Operator instruction
        </label>
        <textarea
          id="operator-instruction"
          rows={2}
          value={text}
          onChange={(event) => setText(event.target.value)}
          placeholder={
            mode === "queue"
              ? "Add context for the next safe checkpoint…"
              : "Revise the request while retaining unaffected evidence…"
          }
        />
        <button type="submit" disabled={isSending || !text.trim()}>
          {isSending
            ? "Acknowledging…"
            : mode === "queue"
              ? "Queue instruction"
              : "Apply redirect"}
        </button>
      </form>
    </section>
  );
}

import { KeyboardEvent, useMemo, useRef, useState } from "react";

import type {
  Candidate,
  EvidenceObservation,
  OperatorRun,
} from "./types";

type CanvasTab = "comparison" | "evidence" | "requirements";

const tabs: { id: CanvasTab; label: string }[] = [
  { id: "comparison", label: "Comparison" },
  { id: "evidence", label: "Evidence" },
  { id: "requirements", label: "Requirements" },
];

interface EvidenceCanvasProps {
  run: OperatorRun;
}

export function EvidenceCanvas({ run }: EvidenceCanvasProps) {
  const [activeTab, setActiveTab] = useState<CanvasTab>("comparison");
  const [selectedEvidenceId, setSelectedEvidenceId] = useState(
    run.evidence[0]?.id ?? "",
  );
  const tabRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const selectedEvidence = useMemo(
    () =>
      run.evidence.find((evidence) => evidence.id === selectedEvidenceId) ??
      run.evidence[0],
    [run.evidence, selectedEvidenceId],
  );

  function selectEvidence(evidenceId: string) {
    setSelectedEvidenceId(evidenceId);
    setActiveTab("evidence");
  }

  function handleTabKeyDown(
    event: KeyboardEvent<HTMLButtonElement>,
    index: number,
  ) {
    let nextIndex: number | undefined;
    if (event.key === "ArrowRight") {
      nextIndex = (index + 1) % tabs.length;
    } else if (event.key === "ArrowLeft") {
      nextIndex = (index - 1 + tabs.length) % tabs.length;
    } else if (event.key === "Home") {
      nextIndex = 0;
    } else if (event.key === "End") {
      nextIndex = tabs.length - 1;
    }
    if (nextIndex === undefined) {
      return;
    }
    event.preventDefault();
    setActiveTab(tabs[nextIndex].id);
    tabRefs.current[nextIndex]?.focus();
  }

  return (
    <section className="evidence-canvas" aria-labelledby="canvas-heading">
      <div className="canvas-heading">
        <div>
          <p className="section-index">Evidence & decision</p>
          <h2 id="canvas-heading">Candidate ledger</h2>
        </div>
        <p>
          {run.evidence.length} observations ·{" "}
          {run.evidence.filter((item) => item.state === "conflicting").length}{" "}
          conflicts
        </p>
      </div>

      <div className="canvas-tabs" role="tablist" aria-label="Decision views">
        {tabs.map((tab, index) => (
          <button
            key={tab.id}
            ref={(node) => {
              tabRefs.current[index] = node;
            }}
            id={`${tab.id}-tab`}
            type="button"
            role="tab"
            aria-selected={activeTab === tab.id}
            aria-controls={`${tab.id}-panel`}
            tabIndex={activeTab === tab.id ? 0 : -1}
            onClick={() => setActiveTab(tab.id)}
            onKeyDown={(event) => handleTabKeyDown(event, index)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === "comparison" ? (
        <ComparisonPanel
          run={run}
          onSelectEvidence={selectEvidence}
        />
      ) : null}
      {activeTab === "evidence" ? (
        <EvidencePanel
          evidence={run.evidence}
          selected={selectedEvidence}
          onSelect={setSelectedEvidenceId}
        />
      ) : null}
      {activeTab === "requirements" ? (
        <div
          className="requirements-panel"
          id="requirements-panel"
          role="tabpanel"
          aria-labelledby="requirements-tab"
        >
          <header>
            <strong>Request revision {run.session.revision}</strong>
            <span>{run.requirements.length} typed criteria</span>
          </header>
          <dl>
            {run.requirements.map((requirement) => (
              <div key={requirement.id}>
                <dt>
                  {requirement.label}
                  {requirement.mandatory ? <span>Mandatory</span> : null}
                </dt>
                <dd>{requirement.value}</dd>
              </div>
            ))}
          </dl>
        </div>
      ) : null}
    </section>
  );
}

function ComparisonPanel({
  run,
  onSelectEvidence,
}: {
  run: OperatorRun;
  onSelectEvidence: (evidenceId: string) => void;
}) {
  if (!run.candidates.length) {
    return (
      <div
        className="canvas-empty"
        id="comparison-panel"
        role="tabpanel"
        aria-labelledby="comparison-tab"
      >
        Comparison begins when candidate evidence is available.
      </div>
    );
  }

  return (
    <div
      className="comparison-panel"
      id="comparison-panel"
      role="tabpanel"
      aria-labelledby="comparison-tab"
    >
      <div className="comparison-scroll">
        <table>
          <caption className="sr-only">
            Candidate comparison with evidence coverage
          </caption>
          <thead>
            <tr>
              <th scope="col">Candidate</th>
              <th scope="col">Delivered cost</th>
              <th scope="col">Lead time</th>
              <th scope="col">Mandatory</th>
              <th scope="col">Evidence</th>
            </tr>
          </thead>
          <tbody>
            {run.candidates.map((candidate) => (
              <CandidateRow
                key={candidate.id}
                candidate={candidate}
                evidence={run.evidence}
                onSelectEvidence={onSelectEvidence}
              />
            ))}
          </tbody>
        </table>
      </div>
      <div className="comparison-note">
        <span aria-hidden="true">i</span>
        <p>
          Ranking is withheld until every mandatory criterion is supported or
          explicitly unresolved. No confidence percentage is inferred.
        </p>
      </div>
    </div>
  );
}

function CandidateRow({
  candidate,
  evidence,
  onSelectEvidence,
}: {
  candidate: Candidate;
  evidence: EvidenceObservation[];
  onSelectEvidence: (evidenceId: string) => void;
}) {
  const firstInspectable = candidate.claims
    .flatMap((claim) => claim.observationIds)
    .find((id) => evidence.some((item) => item.id === id));

  return (
    <tr>
      <th scope="row">
        <strong>{candidate.name}</strong>
        <small>{candidate.location}</small>
      </th>
      <td>{candidate.totalCost}</td>
      <td>{candidate.leadTime}</td>
      <td>
        <span className={`evidence-state ${candidate.mandatoryStatus}`}>
          {candidate.mandatoryStatus}
        </span>
      </td>
      <td>
        {firstInspectable ? (
          <button
            className="evidence-link"
            type="button"
            onClick={() => onSelectEvidence(firstInspectable)}
          >
            {candidate.evidenceCoverage} verified
          </button>
        ) : (
          candidate.evidenceCoverage
        )}
      </td>
    </tr>
  );
}

function EvidencePanel({
  evidence,
  selected,
  onSelect,
}: {
  evidence: EvidenceObservation[];
  selected?: EvidenceObservation;
  onSelect: (evidenceId: string) => void;
}) {
  return (
    <div
      className="evidence-panel"
      id="evidence-panel"
      role="tabpanel"
      aria-labelledby="evidence-tab"
    >
      <div className="evidence-index" aria-label="Evidence observations">
        {evidence.map((item) => (
          <button
            key={item.id}
            type="button"
            className={selected?.id === item.id ? "selected" : ""}
            aria-pressed={selected?.id === item.id}
            onClick={() => onSelect(item.id)}
          >
            <span className={`state-mark ${item.state}`} aria-hidden="true" />
            <span>
              <strong>{item.title}</strong>
              <small>{item.sourceLabel}</small>
            </span>
          </button>
        ))}
      </div>
      {selected ? (
        <article className="evidence-detail" aria-live="polite">
          <header>
            <div>
              <p className="section-index">{selected.state}</p>
              <h3>{selected.title}</h3>
            </div>
            <strong>{selected.value}</strong>
          </header>
          <blockquote>{selected.excerpt}</blockquote>
          <dl>
            <div>
              <dt>Source</dt>
              <dd>
                <a href={selected.sourceUrl}>{selected.sourceLabel}</a>
              </dd>
            </div>
            <div>
              <dt>Observed</dt>
              <dd>{selected.observedAt}</dd>
            </div>
            <div>
              <dt>Content hash</dt>
