  .operator-shell {
    grid-template-columns: 12.5rem minmax(0, 1fr);
  }

  .run-facts {
    grid-template-columns: repeat(3, 1fr);
  }

  .run-facts div:nth-child(4) {
    border-left: 0;
    border-top: 1px solid var(--line);
  }

  .run-facts div:nth-child(5),
  .run-facts div:nth-child(6) {
    border-top: 1px solid var(--line);
  }

  .workbench-grid {
    display: block;
  }

  .work-tree-panel,
  .evidence-canvas {
    min-height: auto;
    border-right: 0;
    border-bottom: 1px solid var(--ink);
  }

  .action-rail {
    display: block;
  }

  .artifact-section {
    border-right: 0;
    border-bottom: 1px solid var(--ink);
  }

  .command-dock {
    position: static;
    grid-template-columns: 1fr;
  }
}

