    min-height: 4.5rem;
  }

  .session-list {
    display: flex;
    overflow-x: auto;
  }

  .session-list > button {
    min-width: 15rem;
    border-right: 1px solid rgb(255 255 255 / 15%);
  }

  .source-disclosure {
    display: none;
  }

  .run-header {
    display: block;
  }

  .run-controls {
    margin-top: 1.2rem;
  }

  .run-facts {
    grid-template-columns: 1fr 1fr;
  }

  .run-facts div:nth-child(3),
  .run-facts div:nth-child(5) {
    border-left: 0;
  }

  .run-facts div:nth-child(3) {
    border-top: 1px solid var(--line);
  }

  .run-facts div:nth-child(4) {
    border-left: 1px solid var(--line);
  }

  .evidence-panel {
    display: block;
  }

  .evidence-index {
    display: flex;
    overflow-x: auto;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .evidence-index button {
    min-width: 12rem;
    border-right: 1px solid var(--line-soft);
  }

  .command-dock form {
    grid-template-columns: 1fr;
  }

  .command-dock fieldset {
    display: flex;
  }

  .command-dock button[type="submit"] {
    min-height: 2.75rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

